/* Tutelles : [civilisation soumise, puissance dominante, nature, début, fin, intitulé] */
const SEED_SUBJ = [
["egypte","koush","province",-747,-671,"sous les pharaons koushites"],
["egypte","assyrie","occupation",-671,-656,"occupation assyrienne"],
["egypte","achemenides","province",-525,-404,"première domination perse"],
["egypte","achemenides","province",-343,-332,"seconde domination perse"],
["egypte","macedoine","province",-332,-332,"conquête macédonienne"],
["babylone","assyrie","vassal",-729,-627,""],
["phenicie","assyrie","vassal",-730,-627,""],
["phenicie","babylone","vassal",-605,-539,""],
["grece","macedoine","tutelle",-338,-200,"hégémonie macédonienne"],
["grece","rome-rep","province",-146,-146,""],
["celtes","rome-rep","province",-51,-50,""],
["lagides","rome-rep","protectorat",-55,-30,"royaume client de Rome"],
["portugal","espagne","union",1580,1640,"Union ibérique"],
["moghol","angleterre","protectorat",1803,1857,"tutelle de la Compagnie des Indes"],
["mali","songhai","vassal",1500,1591,""],
["kongo","portugal","protectorat",1665,1857,""],
["rus","mongols","tutelle",1240,1240,"joug mongol"]
];

function buildSeed() {
  const out = { civs: [], territories: [], events: [], pois: [], links: [], subjections: [] };
  const wiki = t => ({ label: "Wikipédia — " + t, url: "https://fr.wikipedia.org/wiki/" + encodeURIComponent(t.replace(/ /g, "_")) });
  for (const [id, name, start, end, color, region, description] of SEED_CIVS)
    out.civs.push({ id, name, start, end, color, region, description, links: [wiki(name)] });
  const known = new Set(out.civs.map(c => c.id));
  let n = 0;
  for (const [civId, label, start, end, rings] of SEED_TERR) {
    if (!known.has(civId)) continue;
    out.territories.push({ id: "ter-s" + (n++), civId, label, start, end, rings });
  }
  /* Continuité : chaque emprise reste affichée jusqu'à la suivante, et la
     première remonte au début de la civilisation. Les dates restent modifiables. */
  for (const c of out.civs) {
    const ts = out.territories.filter(t => t.civId === c.id).sort((a, b) => a.start - b.start);
    if (!ts.length) continue;
    ts[0].start = Math.min(ts[0].start, c.start);
    for (let i = 0; i < ts.length - 1; i++) ts[i].end = Math.max(ts[i].end, ts[i + 1].start - 1);
    ts[ts.length - 1].end = Math.max(ts[ts.length - 1].end, c.end);
  }
  n = 0;
  const mkEv = o => Object.assign({
    id: "evt-s" + (n++), civId: null, parentId: null, year: 0, end: null, kind: "jalon",
    title: "", description: "", links: [], arrows: [], lon: null, lat: null
  }, o);
  for (const [civId, year, title, description, end] of SEED_EVENTS)
    out.events.push(mkEv({ civId: civId && known.has(civId) ? civId : null, year, end: end ?? year, title, description }));
  for (const [civId, start, end, title, description, arrows, steps] of SEED_CAMPAIGNS) {
    const cid = known.has(civId) ? civId : null;
    const parent = mkEv({
      civId: cid, year: start, end, title, description,
      arrows: arrows.map(([label, dash, pts]) => ({ label, dash: !!dash, pts }))
    });
    out.events.push(parent);
    for (const [y, kind, t, lon, lat, d] of steps)
      out.events.push(mkEv({ civId: cid, parentId: parent.id, year: y, end: y, kind, title: t, lon, lat, description: d }));
  }
  n = 0;
  for (const [civId, kind, name, lon, lat, start, end, description] of SEED_POIS)
    out.pois.push({ id: "poi-s" + (n++), civId: civId && known.has(civId) ? civId : null, kind, name, lon, lat, start, end, description, links: [] });
  const evByTitle = new Map();
  for (const e of out.events) if (!evByTitle.has(e.title)) evByTitle.set(e.title, e.id);
  n = 0;
  for (const [from, to, label, evt] of SEED_LINKS) {
    if (!known.has(from) || !known.has(to)) continue;
    out.links.push({ id: "lnk-s" + (n++), from, to, label, eventId: evt ? (evByTitle.get(evt) || null) : null });
  }
  n = 0;
  for (const [civId, overId, kind, start, end, label] of SEED_SUBJ) {
    if (!known.has(civId) || !known.has(overId)) continue;
    out.subjections.push({ id: "sub-s" + (n++), civId, overId, kind, start, end, label });
  }
  return out;
}
module.exports={buildSeed};
